/* Positive target thermal normalizers from certified interior material
 * regions. This reads the preserved finite CONTROL, never sets a cell U. */
#define GFS_CURVED_BRANCH_LIBRARY
#include "test_curved_branch_v1.cpp"
struct Region {size_t source;curved_bounds::Tri triangle;I position[2];R area=0,U=0,M=0,Jhi=0,lipschitz=0,margin=0;};
static I area_interval(const curved_bounds::Tri &t){using curved_branches::tight_add;using curved_branches::tight_mul;I ux=tight_add(I(t[1][0]),I(-t[0][0])),uy=tight_add(I(t[1][1]),I(-t[0][1])),vx=tight_add(I(t[2][0]),I(-t[0][0])),vy=tight_add(I(t[2][1]),I(-t[0][1]));return tight_add(tight_mul(ux,vy),-tight_mul(uy,vx))/I(2);}
static bool contained(const curved_branches::FixedMap &m,const curved_bounds::Tri &t){for(auto x:t)for(int k=0;k<3;k++){I value=curved_branches::tight_add(curved_branches::tight_add(curved_branches::tight_mul(m.source_exact_n[k][0],I(x[0])),curved_branches::tight_mul(m.source_exact_n[k][1],I(x[1]))),-m.source_exact_c[k]);if(value.lo<0)return false;}return true;}
struct Inspection {Region region;bool impossible=false,certified=false;};
static Inspection inspect(size_t it,const curved_bounds::Tri &t,int target,const curved::Packet &p,const curved_branches::FixedMap &map,const std::vector<curved_partition::Site> &site,const std::vector<R> &weights){
    Inspection out;out.region.source=it;out.region.triangle=t;if(!contained(map,t)){out.impossible=true;return out;}auto bound=curved_bounds::enclose(p.record[it],t,p.parameters[3]);for(int d=0;d<2;d++){R lo=t[0][d],hi=lo;for(int a=1;a<3;a++){lo=std::min(lo,t[a][d]);hi=std::max(hi,t[a][d]);}out.region.position[d]=I(lo,hi)+bound.displacement[d];}bool owner=true;R margin=1e99L;
    for(size_t k=0;k<site.size();k++)if((int)k!=target){auto plane=curved_events::plane(site,weights,target,k);I value=plane.n[0]*out.region.position[0]+plane.n[1]*out.region.position[1]-plane.c;if(value.lo>0){out.impossible=true;return out;}owner=owner && value.hi<0;margin=std::min(margin,-value.hi);}
    auto area=area_interval(t);out.region.area=area.lo;out.region.Jhi=bound.J.hi;out.region.lipschitz=bound.lipschitz;out.region.margin=margin;if(!(owner && area.lo>0 && bound.J.lo>0 && bound.lipschitz<1))return out;
    /* <=8ulp powl model, rounded downward with a much wider64-eps guard. */
    R power=powl(bound.J.hi,1-p.parameters[1]);power=curved_bounds::down(power*(1-64*LDBL_EPSILON));I thermal=I(area.lo)*I(p.parameters[2])*I(power)/(I(p.parameters[1])-I(1)),mass=I(area.lo)*I(p.parameters[6]);out.region.U=thermal.lo;out.region.M=mass.lo;out.certified=thermal.lo>0 && mass.lo>0;return out;
}
static bool disjoint(const Region &a,const Region &b){for(int k=0;k<2;k++)if(a.position[k].hi<b.position[k].lo || b.position[k].hi<a.position[k].lo)return true;return false;}
static curved_bounds::Tri source_triangle(const curved::Record &r){curved_bounds::Tri t;for(int a=0;a<3;a++)for(int k=0;k<2;k++)t[a][k]=r.triangle.geometry.x[a][k];return t;}
static curved_bounds::Tri interior_half(const curved_bounds::Tri &t){curved_bounds::Tri out;for(int k=0;k<2;k++){R center=(t[0][k]+t[1][k]+t[2][k])/3;for(int a=0;a<3;a++)out[a][k]=center+(t[a][k]-center)/2;}return out;}
int main(int argc,char **argv){
    int provided;MPI_Init_thread(&argc,&argv,MPI_THREAD_FUNNELED,&provided);active_mpi=true;need(argc==6,"same packet sites guard new output 225|137|lens");auto p=curved::read(argv[1]);auto site=curved_partition::read_sites(argv[2]);auto weights=read_weights(argv[3],site);bool lens=std::string(argv[5])=="lens";size_t focus=lens?0:atoi(argv[5]);need(lens || focus==225 || focus==137,"bounded target-normalizer bundle");if(lens)p=lens_setup(site,weights);need(p.parameters[1]>1 && p.parameters[2]>0 && p.parameters[6]>0 && p.parameters[9]>=0,"positive physical finite-control pressure/density, no floor modification");auto focusbound=positive_source_bounds(p.record[focus],source_triangle(p.record[focus]),p.parameters[3]);int own=0;for(size_t k=0;k<site.size();k++)if(site[k].id==p.record[focus].cell)own=k;auto candidate=source_candidates(p.record[focus],focusbound,site,weights,own);std::map<size_t,curved_branches::FixedMap> cache;
    std::string dest=argv[4];FILE *rows=fopen((dest+"/target_lower.csv").c_str(),"w"),*regions=fopen((dest+"/interior_regions.csv").c_str(),"w");need(rows && regions,"positive-region proof ledgers");fprintf(rows,"target,U_lower,M_lower,reference_area_lower,regions,source_boxes,normalizer_positive,partial_budget_share\n");fprintf(regions,"target,source_triangle,x0,y0,x1,y1,x2,y2,position_xlo,position_xhi,position_ylo,position_yhi,area_lower,J_upper,lipschitz,owner_margin,U_lower,M_lower\n");bool pass=true;R minU=1e99L;uint64_t totalboxes=0;
    for(int target:candidate){std::vector<size_t> matching;for(size_t it=0;it<p.record.size();it++)if(p.record[it].cell==site[target].id)matching.push_back(it);std::vector<Region> accepted;uint64_t boxes=0;
        auto getmap=[&](size_t it)->const curved_branches::FixedMap&{auto found=cache.find(it);if(found==cache.end())found=cache.emplace(it,curved_branches::fixed_map(p.record[it],p.parameters[3])).first;return found->second;};auto retain=[&](const Inspection &q){if(!q.certified)return false;for(const auto &old:accepted)if(!disjoint(old,q.region))return false;accepted.push_back(q.region);return true;};
        for(size_t it:matching){auto t=interior_half(source_triangle(p.record[it]));auto q=inspect(it,t,target,p,getmap(it),site,weights);boxes++;retain(q);}
        /* If no simple interior piece is certified, use a bounded targeted
         * source search. Power inequalities exclude whole boxes; no global
         * spatial scan, density replacement or cell-temperature floor. */
        if(accepted.empty()){struct Node {size_t it;curved_bounds::Tri triangle;int depth;};std::vector<Node> stack;if(matching.empty()){for(size_t it=0;it<p.record.size();it++)stack.push_back({it,source_triangle(p.record[it]),0});}else for(size_t it:matching)stack.push_back({it,source_triangle(p.record[it]),0});while(!stack.empty() && boxes<256){size_t largest=0;R largest_area=-1;for(size_t k=0;k<stack.size();k++){R area=area_interval(stack[k].triangle).hi;if(area>largest_area){largest_area=area;largest=k;}}auto node=stack[largest];stack.erase(stack.begin()+largest);auto q=inspect(node.it,node.triangle,target,p,getmap(node.it),site,weights);boxes++;if(q.certified){retain(q);continue;}if(q.impossible || node.depth>=16)continue;for(auto child:curved_bounds::split(node.triangle))stack.push_back({node.it,child,node.depth+1});}}
        R U=0,M=0,A=0;for(const auto &q:accepted){U=curved_bounds::down(U+q.U);M=curved_bounds::down(M+q.M);A=curved_bounds::down(A+q.area);fprintf(regions,"%llu,%zu,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg\n",(unsigned long long)site[target].id,q.source,q.triangle[0][0],q.triangle[0][1],q.triangle[1][0],q.triangle[1][1],q.triangle[2][0],q.triangle[2][1],q.position[0].lo,q.position[0].hi,q.position[1].lo,q.position[1].hi,q.area,q.Jhi,q.lipschitz,q.margin,q.U,q.M);}bool positive=U>0 && M>0;pass=pass && positive;minU=std::min(minU,U);totalboxes+=boxes;R share=1.L/(2*p.record.size()+1);fprintf(rows,"%llu,%.21Lg,%.21Lg,%.21Lg,%zu,%llu,%d,%.21Lg\n",(unsigned long long)site[target].id,U,M,A,accepted.size(),(unsigned long long)boxes,positive,share);}
    fclose(rows);fclose(regions);printf("{\"scope\":\"positive thermal lower bounds from target-owned injective interior images; disjoint image boxes permit addition; no E-K, no thermal state change\",\"triangle\":%zu,\"lens\":%s,\"targets\":%zu,\"source_boxes\":%llu,\"all_target_normalizers_positive\":%s,\"minimum_U_lower\":%.17Lg,\"powl_ulp_assumption\":8,\"remaining_target_contributions_complete\":false,\"full_cold_transfer_proved\":false}\n",focus,lens?"true":"false",candidate.size(),(unsigned long long)totalboxes,pass?"true":"false",minU);active_mpi=false;MPI_Finalize();return pass?0:2;
}
